//! Themes: nvim-style colour schemes as JSON (see themes/theme.schema.json).
//! A theme is a named palette plus UI slots pointing at palette names. Perspective colours come from
//! hue slots and are nudged toward the text colour until they read against the background.
use eframe::egui::Color32;
use serde::Deserialize;
use std::collections::BTreeMap;
use std::path::PathBuf;
use std::sync::RwLock;

/// Popular editor/terminal schemes (Tokyo Night, Catppuccin, Everforest, Gruvbox, Rosé Pine…), generated by
/// themes/make_popular.py from the schemes' upstream colours.
pub const POPULAR: &str = include_str!("../themes/popular.json");

/// Built-ins first, then the popular schemes.
pub fn builtins() -> Vec<Theme> {
    let mut out: Vec<Theme> = BUILTIN.iter().map(|j| Theme::parse(j).expect("built-in theme")).collect();
    let list: Vec<serde_json::Value> = serde_json::from_str(POPULAR).expect("popular.json");
    out.extend(list.iter().map(|v| Theme::parse(&v.to_string()).expect("popular theme")));
    out
}

pub const BUILTIN: [&str; 4] = [
    include_str!("../themes/focus-dark.json"),
    include_str!("../themes/focus-light.json"),
    include_str!("../themes/kanagawa-paper-ink.json"),
    include_str!("../themes/kanagawa-paper-canvas.json"),
];

#[derive(Deserialize)]
struct ThemeFile {
    name: String,
    mode: String,
    #[serde(default)]
    palette: BTreeMap<String, String>,
    ui: BTreeMap<String, String>,
    #[serde(default)]
    map: Option<String>,
}

/// Resolved colours for every UI slot.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Colors {
    pub dark: bool,
    pub map_dark: bool,
    pub bg: Color32,
    pub text: Color32,
    pub accent: Color32,
    pub dim: Color32,
    pub faint: Color32,
    pub rail: Color32,
    pub toolbar: Color32,
    pub column: Color32,
    pub inspector: Color32,
    pub field: Color32,
    pub pill: Color32,
    pub pill_hover: Color32,
    pub sel_row: Color32,
    pub rail_sel: Color32,
    pub line: Color32,
    pub on_accent: Color32,
    pub overdue: Color32,
    pub due_soon: Color32,
    pub flag: Color32,
    pub next: Color32,
    pub tag_pill: Color32,
    pub tag_text: Color32,
    pub badge: Color32,
    pub link: Color32,
    pub hues: [Color32; 9],
}

pub const HUES: [&str; 9] = ["red", "orange", "yellow", "green", "cyan", "blue", "indigo", "purple", "violet"];

#[derive(Clone)]
pub struct Theme {
    pub name: String,
    pub dark: bool,
    pub colors: Colors,
}

pub fn hex(s: &str) -> Option<Color32> {
    let s = s.strip_prefix('#')?;
    if s.len() != 6 {
        return None;
    }
    let v = u32::from_str_radix(s, 16).ok()?;
    Some(Color32::from_rgb((v >> 16) as u8, (v >> 8) as u8, v as u8))
}

pub fn mix(a: Color32, b: Color32, t: f32) -> Color32 {
    let l = |x: u8, y: u8| (x as f32 + (y as f32 - x as f32) * t).round() as u8;
    Color32::from_rgb(l(a.r(), b.r()), l(a.g(), b.g()), l(a.b(), b.b()))
}

fn luminance(c: Color32) -> f32 {
    let ch = |v: u8| {
        let v = v as f32 / 255.0;
        if v <= 0.03928 { v / 12.92 } else { ((v + 0.055) / 1.055).powf(2.4) }
    };
    0.2126 * ch(c.r()) + 0.7152 * ch(c.g()) + 0.0722 * ch(c.b())
}

/// WCAG contrast ratio.
pub fn contrast(a: Color32, b: Color32) -> f32 {
    let (x, y) = (luminance(a), luminance(b));
    (x.max(y) + 0.05) / (x.min(y) + 0.05)
}

/// Moves `c` toward the far end (white on dark, black on light) until it reaches `min` contrast with `bg`.
pub fn readable(c: Color32, bg: Color32, min: f32) -> Color32 {
    let target = if luminance(bg) < 0.5 { Color32::WHITE } else { Color32::BLACK };
    let mut out = c;
    let mut t = 0.0;
    while contrast(out, bg) < min && t < 1.0 {
        t += 0.05;
        out = mix(c, target, t);
    }
    out
}

impl Theme {
    pub fn parse(json: &str) -> Result<Theme, String> {
        let f: ThemeFile = serde_json::from_str(json).map_err(|e| e.to_string())?;
        let look = |key: &str| -> Option<Color32> {
            let v = f.ui.get(key)?;
            hex(v).or_else(|| f.palette.get(v).and_then(|p| hex(p)))
        };
        for k in f.ui.keys() {
            if look(k).is_none() {
                return Err(format!("{}: ui.{k} points at an unknown palette name or bad colour", f.name));
            }
        }
        let bg = look("bg").ok_or(format!("{}: ui.bg is required", f.name))?;
        let text = look("fg").ok_or(format!("{}: ui.fg is required", f.name))?;
        let accent = look("accent").ok_or(format!("{}: ui.accent is required", f.name))?;
        let dark = f.mode != "light";
        let shade = |t: f32| mix(bg, if dark { Color32::BLACK } else { Color32::WHITE }, t);
        let lift = |t: f32| mix(bg, text, t);
        let dim = look("fg_dim").unwrap_or(mix(text, bg, 0.4));
        let hue = |k: &str, fallback: Color32| look(k).unwrap_or(fallback);
        let red = hue("red", look("overdue").unwrap_or(Color32::from_rgb(0xd0, 0x50, 0x48)));
        let hues = [
            red,
            hue("orange", Color32::from_rgb(0xe0, 0x90, 0x40)),
            hue("yellow", Color32::from_rgb(0xd0, 0xb0, 0x40)),
            hue("green", Color32::from_rgb(0x60, 0xb0, 0x58)),
            hue("cyan", Color32::from_rgb(0x50, 0xa8, 0xb8)),
            hue("blue", accent),
            hue("indigo", accent),
            hue("purple", Color32::from_rgb(0x88, 0x78, 0xd0)),
            hue("violet", Color32::from_rgb(0xa0, 0x60, 0xe0)),
        ];
        let colors = Colors {
            dark,
            map_dark: f.map.as_deref().map(|m| m == "dark").unwrap_or(dark),
            bg,
            text,
            accent,
            dim,
            faint: look("fg_faint").unwrap_or(mix(text, bg, 0.65)),
            rail: look("rail").unwrap_or(shade(0.06)),
            toolbar: look("toolbar").unwrap_or(shade(0.04)),
            column: look("column").unwrap_or(bg),
            inspector: look("inspector").unwrap_or(shade(0.06)),
            field: look("field").unwrap_or(lift(0.08)),
            pill: look("pill").unwrap_or(lift(0.1)),
            pill_hover: look("pill_hover").unwrap_or(lift(0.16)),
            sel_row: look("selection").unwrap_or(mix(bg, accent, 0.35)),
            rail_sel: look("rail_selection").unwrap_or(lift(0.1)),
            line: look("line").unwrap_or(lift(0.07)),
            on_accent: look("on_accent").unwrap_or(Color32::WHITE),
            overdue: look("overdue").unwrap_or(red),
            due_soon: look("due_soon").unwrap_or(hues[2]),
            flag: look("flagged").unwrap_or(hues[1]),
            next: look("next").unwrap_or(hues[8]),
            tag_pill: look("tag_pill").unwrap_or(lift(0.14)),
            tag_text: look("tag_text").unwrap_or(dim),
            badge: look("badge").unwrap_or(lift(0.2)),
            link: look("link").unwrap_or(accent),
            hues,
        };
        Ok(Theme { name: f.name, dark, colors })
    }
}

/// Built-ins plus every *.json in the user themes folder (a bad file is reported, not fatal).
pub fn load_all() -> (Vec<Theme>, Vec<String>) {
    let mut out = builtins();
    let mut errors = vec![];
    if let Ok(rd) = std::fs::read_dir(user_dir()) {
        let mut paths: Vec<PathBuf> = rd.filter_map(|e| e.ok()).map(|e| e.path()).filter(|p| p.extension().is_some_and(|x| x == "json")).collect();
        paths.sort();
        for p in paths {
            if p.file_name().is_some_and(|n| n == "theme.schema.json") {
                continue;
            }
            match std::fs::read_to_string(&p).map_err(|e| e.to_string()).and_then(|j| Theme::parse(&j)) {
                Ok(t) => {
                    out.retain(|x| x.name != t.name); // a user file can override a built-in by name
                    out.push(t);
                }
                Err(e) => errors.push(format!("{}: {e}", p.display())),
            }
        }
    }
    (out, errors)
}

pub fn user_dir() -> PathBuf {
    crate::model::default_path().parent().map(|p| p.join("themes")).unwrap_or_else(|| PathBuf::from("themes"))
}

/// Writes the schema and the built-in themes as starting points into the user folder (never overwrites).
pub fn seed_user_dir() -> std::io::Result<PathBuf> {
    let dir = user_dir();
    std::fs::create_dir_all(&dir)?;
    let schema = dir.join("theme.schema.json");
    if !schema.exists() {
        std::fs::write(schema, include_str!("../themes/theme.schema.json"))?;
    }
    let example = dir.join("my-theme.json.example");
    if !example.exists() {
        std::fs::write(example, include_str!("../themes/kanagawa-paper-ink.json"))?;
    }
    Ok(dir)
}

// ponytail: one process-wide current palette; painting code reads it via c(). Per-window themes would need it passed down.
static CURRENT: RwLock<Option<Colors>> = RwLock::new(None);

pub fn set(c: Colors) {
    *CURRENT.write().unwrap() = Some(c);
}

pub fn c() -> Colors {
    CURRENT.read().unwrap().unwrap_or_else(|| Theme::parse(BUILTIN[0]).unwrap().colors)
}

/// Perspective colour for a hue name, adjusted so it always reads on the rail and the outline.
pub fn hue(name: &str) -> Color32 {
    let cs = c();
    let base = HUES.iter().position(|h| *h == name).map(|i| cs.hues[i]).unwrap_or(cs.accent);
    readable(readable(base, cs.bg, 3.0), cs.rail, 3.0)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn builtins_parse_and_read() {
        let all = builtins();
        assert!(all.len() >= 38);
        for name in ["Tokyo Night", "Catppuccin Mocha", "Catppuccin Latte", "Everforest Dark", "Gruvbox Dark", "Rosé Pine", "Nord", "Dracula"] {
            assert!(all.iter().any(|t| t.name == name), "{name}");
        }
        assert_eq!(all.iter().find(|t| t.name == "Catppuccin Mocha").unwrap().colors.bg, hex("#1e1e2e").unwrap()); // upstream colour, unchanged
        assert!(!all.iter().find(|t| t.name == "Catppuccin Latte").unwrap().dark);
        for t in &all {
            for h in t.colors.hues {
                assert!(contrast(readable(h, t.colors.bg, 3.0), t.colors.bg) >= 3.0 - 1e-3, "{}", t.name);
            }
        }
        let ink = Theme::parse(BUILTIN[2]).unwrap();
        assert_eq!(ink.colors.bg, hex("#1F1F28").unwrap());
        assert!(ink.dark);
        let canvas = Theme::parse(BUILTIN[3]).unwrap();
        assert_eq!(canvas.colors.bg, hex("#e1e1de").unwrap());
        assert!(!canvas.dark);
        assert_eq!(Theme::parse(BUILTIN[0]).unwrap().name, "Focus Dark");
    }

    #[test]
    fn bad_reference_is_reported() {
        let e = Theme::parse(r##"{"name":"x","mode":"dark","palette":{},"ui":{"bg":"nope","fg":"#ffffff","accent":"#0000ff"}}"##);
        assert!(e.is_err());
        let ok = Theme::parse(r##"{"name":"x","mode":"light","palette":{},"ui":{"bg":"#ffffff","fg":"#000000","accent":"#0000ff"}}"##).unwrap();
        assert!(!ok.dark && contrast(ok.colors.dim, ok.colors.bg) > 1.5);
    }
}
